[{"order":1,"type":"heading","text":"Basic Input/Output (Console, File I/O) in C#"},{"order":2,"type":"paragraph","text":"This tutorial covers basic input and output operations in C#, focusing on console input/output and file input/output. These are fundamental skills for any C# developer."},{"order":3,"type":"heading","text":"Console Input/Output"},{"order":4,"type":"subheading","text":"Console Output (Writing to the Console)"},{"order":5,"type":"paragraph","text":"The `System.Console` class provides methods for writing output to the console. The most commonly used methods are `Console.WriteLine()` and `Console.Write()`."},{"order":6,"type":"bullet_point","text":"`Console.WriteLine(value)`: Writes the specified value, followed by the current line terminator, to the standard output stream."},{"order":7,"type":"bullet_point","text":"`Console.Write(value)`: Writes the specified value to the standard output stream."},{"order":8,"type":"code","text":"using System;

public class ConsoleOutputExample
{
    public static void Main(string[] args)
    {
        Console.WriteLine("Hello, World!"); // Writes 'Hello, World!' followed by a new line
        Console.Write("This is "); // Writes 'This is '
        Console.Write("on the same line."); // Writes 'on the same line.'
        Console.WriteLine(); // Writes a new line

        int age = 30;
        Console.WriteLine("Age: " + age); // String concatenation
        Console.WriteLine("Age: {0}", age); // Using composite formatting
    }
}"},{"order":9,"type":"subheading","text":"Console Input (Reading from the Console)"},{"order":10,"type":"paragraph","text":"The `System.Console` class also provides methods for reading input from the console. The most common methods are `Console.ReadLine()` and `Console.ReadKey()`."},{"order":11,"type":"bullet_point","text":"`Console.ReadLine()`: Reads a line of characters from the standard input stream. It returns a string representing the input."},{"order":12,"type":"bullet_point","text":"`Console.ReadKey()`: Obtains the next character or function key pressed by the user. The pressed key is optionally displayed in the console window."},{"order":13,"type":"code","text":"using System;

public class ConsoleInputExample
{
    public static void Main(string[] args)
    {
        Console.Write("Enter your name: ");
        string name = Console.ReadLine();

        Console.Write("Enter your age: ");
        string ageString = Console.ReadLine();
        int age = int.Parse(ageString); // Convert string to integer

        Console.WriteLine("Hello, " + name + "! You are " + age + " years old.");

        Console.WriteLine("Press any key to exit...");
        Console.ReadKey();
    }
}"},{"order":14,"type":"heading","text":"File Input/Output"},{"order":15,"type":"subheading","text":"Writing to a File"},{"order":16,"type":"paragraph","text":"To write to a file, you can use the `StreamWriter` class. This class provides methods for writing text to a file."},{"order":17,"type":"code","text":"using System;
using System.IO;

public class FileWriteExample
{
    public static void Main(string[] args)
    {
        string filePath = "output.txt";

        try
        {
            using (StreamWriter writer = new StreamWriter(filePath))
            {
                writer.WriteLine("This is the first line.");
                writer.WriteLine("This is the second line.");
                writer.Write("This is ");
                writer.Write("on the same line.");
            }
            Console.WriteLine("Successfully wrote to file: " + filePath);
        }
        catch (Exception e)
        {
            Console.WriteLine("An error occurred: " + e.Message);
        }
    }
}"},{"order":18,"type":"subheading","text":"Reading from a File"},{"order":19,"type":"paragraph","text":"To read from a file, you can use the `StreamReader` class. This class provides methods for reading text from a file."},{"order":20,"type":"code","text":"using System;
using System.IO;

public class FileReadExample
{
    public static void Main(string[] args)
    {
        string filePath = "output.txt";

        try
        {
            using (StreamReader reader = new StreamReader(filePath))
            {
                string line;
                while ((line = reader.ReadLine()) != null)
                {
                    Console.WriteLine(line);
                }
            }
            Console.WriteLine("Successfully read from file: " + filePath);
        }
        catch (Exception e)
        {
            Console.WriteLine("An error occurred: " + e.Message);
        }
    }
}"},{"order":21,"type":"paragraph","text":"Remember to handle potential exceptions, such as `FileNotFoundException`, when working with files."},{"order":22,"type":"paragraph","text":"These examples provide a basic understanding of console and file I/O in C#. Further exploration of the `System.IO` namespace will reveal more advanced techniques."}]
